dataTransform.transform:
edges.node~>|$|{
"headerText":(
$event := $isNilOrEmpty(event.name) ? " " : " : " & event.name;
$title := workcenter.code & " : " & mode.name & $event;

$r := $parseInt($substring(mode.modeType.color,1,2),16);
$g := $parseInt($substring(mode.modeType.color,3,4),16);
$b := $parseInt($substring(mode.modeType.color,5,6),16);

$color := (($r * 0.299) + ($g * 0.587) + ($b * 0.114)) > 186 ? "#000000" : "#ffffff";

"<span style=\"color:" & $color & "; font-size: 50px;font-weight: bold;\">" & $title & "</span>" 

)

}|

data.__transform:
(
$isNilOrEmpty(data.productionSetupOutput.standardRate) ? "No Rate Data" : (
$total := $sum($$.data.productionSetupOutput.productionSetup.setupMaterials.edges.node.inventory[productStrategyProcessId=$$.data.componentProductStrategyProcessId].quantity.value);
$remaining := $isNilOrEmpty($total) ? 0 : $coalesce([data.standardUsage,0])*$coalesce([data.productionSetupOutput.remainingBalance,0]) - $total;
$result := ($coalesce([$total,0])/$coalesce([data.productionSetupOutput.standardRate,0]))*60;
$remaining < 0 ? $round(0-$remaining,2) & " Units Excess" : $round($result,0) & " mins remaining"
) 
)

